import svgCaptcha from"svg-captcha";import{createUuid}from"./uuid-tools.js";const captchaMap=new Map;export function create(){const e=svgCaptcha.create({size:4,ignoreChars:"O0o1iIl",noise:20,color:!0,background:"#cc9966"}),t=createUuid();return captchaMap.set(t,{id:t,text:e.text.toLowerCase(),overtime:(new Date).getTime()+42e4}),{svg:e.data,id:t}}export function verify(e,t){const a=captchaMap.get(e);return!!a&&(t=(t+="").toLowerCase(),a.text===t&&(captchaMap.delete(e),!0))}export function verifyOverTime(){const e=(new Date).getTime();captchaMap.forEach(t=>{t.overtime>=e||captchaMap.delete(t.id)})}